/** A query inside a transaction negotiates blank-node origins with the transaction's own repository. */
class TestTransactionControllerBNodeOrigin {

	private final String repositoryID = "test-repo";
	private Repository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(connection.getValueFactory().createBNode("stored"),
					connection.getValueFactory().createIRI("urn:p"), connection.getValueFactory().createIRI("urn:o"));
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	@Test
	void aStoredBlankNodeQueriedInsideATransactionIsAReference() throws Exception {
		Transaction txn = new Transaction(repository);
		ActiveTransactionRegistry.INSTANCE.register(txn);
		UUID transactionId = txn.getID();
		MockHttpServletRequest request = new MockHttpServletRequest();
		request.setRequestURI("/repositories/" + repositoryID + "/transactions/" + transactionId);
		request.setPathInfo(repositoryID + "/transactions/" + transactionId);
		request.setMethod(HttpMethod.PUT.name());
		request.setParameter(Protocol.ACTION_PARAM_NAME, "QUERY");
		request.setContentType("application/sparql-query; charset=utf-8");
		request.setContent("SELECT ?s WHERE { ?s <urn:p> <urn:o> }".getBytes(StandardCharsets.UTF_8));
		request.addHeader("Accept", TupleQueryResultFormat.BINARY.getDefaultMIMEType());
		request.addHeader(BNodeOriginTransport.HEADER, BNodeOriginTransport.VERSION);
		MockHttpServletResponse response = new MockHttpServletResponse();
		try {
			ModelAndView result = new TransactionController().handleRequestInternal(request, response);
			result.getView().render(result.getModel(), request, response);
		} finally {
			txn.close();
			ActiveTransactionRegistry.INSTANCE.deregister(txn);
		}

		assertThat(response.getHeader(BNodeOriginTransport.HEADER)).isEqualTo(BNodeOriginTransport.VERSION);
		AtomicReference<BNode> node = new AtomicReference<>();
		BinaryQueryResultParser parser = new BinaryQueryResultParser();
		parser.setQueryResultHandler(new AbstractTupleQueryResultHandler() {
			@Override
			public void handleSolution(BindingSet solution) {
				node.set((BNode) solution.getValue("s"));
			}
		});
		parser.parseQueryResult(new ByteArrayInputStream(response.getContentAsByteArray()));
		RepositoryBNode decoded = (RepositoryBNode) BNodeOriginTransport.decode(node.get());
		assertThat(decoded.getRawID()).isEqualTo("stored");
		assertThat(decoded.isReference()).as("a committed blank node is a repository reference").isTrue();
	}
}
